def sha(b):return hashlib.sha256(b).hexdigest()
def main():
 root=Path(__file__).resolve().parent
 python=root/'.venv/bin/python'
 if not python.exists():raise SystemExit('STOP: copy into ~/RB-ITOS-AI; venv missing')
 decoded={p:zlib.decompress(base64.b85decode(x)) for p,x in PAYLOAD.items()}
 changes={}
 for rel,want in BASELINE.items():
  target=root/rel
  if not target.exists():raise SystemExit(f'STOP: {rel} missing; nothing changed')
  got=sha(target.read_bytes())
  if got==sha(decoded[rel]):continue
  if got!=want:raise SystemExit(f'STOP: {rel} differs from reviewed baseline; nothing changed')
  changes[rel]=decoded[rel]
 if not changes:print('Already applied');return
 backup=root/'data/backups'/('hilega-close-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
 backup.mkdir(parents=True,exist_ok=False)
 for rel,data in changes.items():
  dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(root/rel,dest)
  target=root/rel;tmp=target.with_name(target.name+'.hilega-close.tmp');tmp.write_bytes(data);tmp.replace(target)
 try:
  for cmd in ([str(python),'-m','pytest','-q','tests/test_hilega_directional_candle_ui_v1.py','tests/test_hilega_directional_live_shadow_ui_v1.py'],['git','diff','--check']):
   print('Running:',' '.join(cmd),flush=True);subprocess.run(cmd,cwd=root,check=True)
 except (subprocess.CalledProcessError,OSError) as exc:
  for rel in changes:shutil.copy2(backup/rel,root/rel)
  print('STOP: tests failed; source restored; API/worker untouched',file=sys.stderr)
  raise SystemExit(1) from exc
 print('PASS: fast candle source updated; restart API only to activate. Worker untouched.')
 print('Backup:',backup)
if __name__=='__main__':main()
